// 1. Obtención y parseo de datos de entrada
const inputItem = $input.first().json;
let rawData = inputItem.output || inputItem.text || inputItem;

if (typeof rawData === 'string') {
  try {
    const cleanJson = rawData.replace(/```json/gi, '').replace(/```/gi, '').trim();
    rawData = JSON.parse(cleanJson);
  } catch (e) {
    rawData = { texto_bruto: rawData };
  }
}

// Datos provenientes de la Ingesta Webhook
let ingesta = {};
try {
  ingesta = $('Ingesta Webhook').first().json;
} catch (e) {
  ingesta = {};
}

const documentoId = ingesta.documento_id || rawData.documento_id || "DOC-CLIN-2026-UNKNOWN";
const canalOrigen = ingesta.canal_origen || "Guardia_Emergencias";

// 2. Extracción de sub-objetos (compatibilidad con estructura vieja y nueva de la IA)
const clasifObj = rawData.clasificacion || rawData.documento || {};
const datosExt = rawData.datos_extraidos || {};
const pacienteObj = datosExt.paciente || rawData.paciente || {};
const profesionalObj = datosExt.medico_solicitante || rawData.profesional || {};
const clinicoObj = rawData.clinico || {};
const metaObj = rawData.metadata_control || {};

const tipoDoc = String(clasifObj.tipo_documento || clasifObj.tipo || rawData.tipo_documento || "Desconocido").trim();
const tipoLower = tipoDoc.toLowerCase();

// 3. DETECCIÓN BLINDADA DE IMAGEN Y PRIORIAD
const esEstudioImagen = Boolean(
  clinicoObj.es_estudio_imagen === true ||
  tipoLower.includes("imagen") ||
  tipoLower.includes("radiograf") ||
  tipoLower.includes("ecograf") ||
  tipoLower.includes("tomograf") ||
  tipoLower.includes("laboratorio") ||
  tipoLower.includes("desconocido")
);

const esUrgente = Boolean(
  clasifObj.nivel_prioridad === "Urgente" ||
  clinicoObj.urgencia === true ||
  tipoLower.includes("urgencia")
);

const scoreConfianza = Number(clasifObj.score_confianza_clasificacion || clasifObj.confianza_clasificacion || 0.95);

// 4. LÓGICA DE REVISIÓN HUMANA (Conservando tus reglas exactas)
let requiereRevision = false;
let motivos = [];

if (metaObj.requiere_revision_humana === true || String(metaObj.requiere_revision_humana).toLowerCase() === "true") {
  requiereRevision = true;
  motivos.push("Declarado por IA: Documento o imagen ilegible / requiere revisión");
} else if (!esEstudioImagen) {
  if (tipoLower === "desconocido" || scoreConfianza < 0.60) {
    requiereRevision = true;
    motivos.push("Confianza baja o tipo de documento no identificado");
  }
  const nombrePac = pacienteObj.nome || pacienteObj.nombre_completo;
  if (!nombrePac || String(nombrePac).toLowerCase() === "no claro") {
    requiereRevision = true;
    motivos.push("Nombre de paciente no claro o ilegible");
  }
}

// 5. Construcción de Justificación y Mensajes
const diagnostico = datosExt.diagnostico_principal || clinicoObj.hipotesis_diagnostica || "Sin diagnóstico especificado";
const nombrePaciente = pacienteObj.nome || pacienteObj.nombre_completo || "Paciente";
const carpetaOci = esUrgente ? "urgentes" : "normales";

const justificacion = rawData.justificacion_enrutamiento || 
  (esUrgente ? `Hallazgo crítico o condición urgente detectada (${diagnostico}).` : "Procesamiento estándar sin hallazgos críticos.");

const mensajeAlerta = rawData.alerta_mensaje || 
  (esUrgente ? `ALERTA URGENTE: Informe crítico para el paciente ${nombrePaciente} en ${canalOrigen}.` : null);

// 6. ESTRUCTURA FINAL SOLICITADA
return [{
  json: {
    status: "procesado",
    documento_id: documentoId,
    clasificacion: {
      tipo_documento: esEstudioImagen && tipoLower.includes("desconocido") ? "Informe de Estudio por Imágenes" : tipoDoc,
      especialidad: clasifObj.especialidad || profesionalObj.especialidad || "General",
      nivel_prioridad: esUrgente ? "Urgente" : "Normal",
      score_confianza_clasificacion: scoreConfianza
    },
    datos_extraidos: {
      paciente: {
        nome: pacienteObj.nome || pacienteObj.nombre_completo || null,
        edad: pacienteObj.edad ? Number(pacienteObj.edad) : null
      },
      medico_solicitante: {
        nombre: profesionalObj.nombre || profesionalObj.nombre_completo || "No especificado",
        matricula: profesionalObj.matricula || profesionalObj.registro_profesional || "Sin matrícula"
      },
      estudio_realizado: datosExt.estudio_realizado || clinicoObj.estudio_realizado || "No especificado",
      diagnostico_principal: diagnostico,
      cie10_sugerido: datosExt.cie10_sugerido || "N/A"
    },
    decision_enrutamiento: {
      destino_principal: "", // Se llena automáticamente en el nodo de la Cola correspondiente
      requiere_auditoria_humana: requiereRevision,
      justificacion_enrutamiento: justificacion,
      notificacion_generada: {
        canal: `Alerta_${canalOrigen}`,
        mensaje: mensajeAlerta
      }
    },
    almacenamiento_oci: {
      bucket: "mediflow-documentos-clinicos",
      ruta_objeto: `procesados/${carpetaOci}/${documentoId}.json`,
      status_backup: "exito"
    }
  }
}];

// Obtener el elemento de entrada
const item = $input.first();

// Buscar la propiedad binaria (habitualmente 'data')
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error("No se encontró ningún archivo binario en la entrada de imagen.");
}

const binaryPropertyName = binaryKeys[0];
const binaryData = item.binary[binaryPropertyName];

// Normalizar MIME Type para extensiones conflictivas como jfif
let mimeType = binaryData.mimeType || 'image/jpeg';
if (mimeType.includes('jfif') || binaryData.fileExtension === 'jfif') {
  mimeType = 'image/jpeg';
}

return {
  json: {
    ...item.json,
    es_imagen_normalizada: true,
    mime_type_detectado: mimeType
  },
  binary: {
    data: {
      ...binaryData,
      mimeType: mimeType,
      fileExtension: mimeType.split('/')[1] || 'jpg'
    }
  }
};

options.systemMessage:
Eres un sistema experto en inspección visual de documentos médicos, exámenes de laboratorio e imagenología (incluyendo documentos escaneados y fotografías).

Tu tarea es realizar OCR visual y análisis clínico de la imagen proporcionada para extraer todos los datos del paciente y el contenido médico.

REGLAS DE CLASIFICACIÓN Y EXTRACCIÓN:
1. Si el documento es una radiografía, ecografía, tomografía, orden o examen de laboratorio, asigna en documento.tipo: "Informe de Imagenología / Laboratorio" y establece clinico.es_estudio_imagen en true.
2. Si la imagen es borrosa, oscura o ilegible, asigna metadata_control.requiere_revision_humana en true y detalla los motivos.
3. Extrae con precisión el nombre completo del paciente, su número de RUT/DNI/Identificación, fecha de nacimiento y previsión si están visibles.
4. Responde ÚNICAMENTE en formato JSON plano matching la siguiente estructura exacta:

{
  "documento": {
    "tipo": "Informe de Imagenología / Laboratorio",
    "confianza_clasificacion": 0.95
  },
  "paciente": {
    "nombre_completo": "Nombre encontrado o 'No claro'",
    "identificacion": "RUT o DNI encontrado o 'Desconocido'",
    "edad": null,
    "fecha_nacimiento": null,
    "prevision": null
  },
  "profesional": {
    "nombre_completo": "Nombre del profesional o 'No especificado'",
    "especialidad": "",
    "matricula": ""
  },
  "clinico": {
    "urgencia": false,
    "hipotesis_diagnostica": "Descripción breve del examen, hallazgos o motivo",
    "medicamentos": [],
    "es_estudio_imagen": true
  },
  "metadata_control": {
    "requiere_revision_humana": false,
    "motivos_revision": []
  }
}

